import {createAtlasRuntimeExpansion,type AtlasExpansionState} from './atlas-runtime-expansion';

/** Expand the existing page host; the iframe and both learning channels stay mounted. */
function HeadAtlasExpansionTools({frame,src,sourceRevision,attempt}:{frame:{current:HTMLIFrameElement|null};src:string;sourceRevision:string;attempt:number}){
  const tools=useRef<HTMLDivElement>(null),button=useRef<HTMLButtonElement>(null);
  const expansion=useRef<ReturnType<typeof createAtlasRuntimeExpansion>|null>(null);
  const [state,setState]=useState<AtlasExpansionState>({active:false,pending:false,message:null});
  useLayoutEffect(()=>{
    const owner=tools.current?.closest<HTMLElement>('main.head-comparison-module-page');
    const element=frame.current;
    if(!owner||!element)return;
    const doc=owner.ownerDocument;
    let wasOwned=doc.fullscreenElement===owner;
    const controller=createAtlasRuntimeExpansion({owner,doc,frame:element,change:next=>{
      if(wasOwned&&!next.active&&!doc.fullscreenElement){
        queueMicrotask(()=>{
          if(expansion.current===controller&&!doc.fullscreenElement&&doc.activeElement===doc.body&&button.current?.isConnected){
            button.current.focus({preventScroll:true});
          }
        });
      }
      wasOwned=next.active;
      setState(next);
    }});
    expansion.current=controller;
    const refresh=()=>{if(frame.current===element)controller.refreshFrame(element);};
    element.addEventListener('load',refresh);
    return()=>{
      if(expansion.current===controller)expansion.current=null;
      element.removeEventListener('load',refresh);
      controller.retire();
    };
  },[frame,src,sourceRevision,attempt]);
  return <div ref={tools} className="head-linked-viewer-tools">
    <button ref={button} type="button" aria-pressed={state.active} disabled={state.pending}
      onClick={()=>state.active?expansion.current?.exit():expansion.current?.request()}>
      {state.active?'Restore viewer':'Expand viewer'}
    </button>
    {state.message&&<p role="status" aria-live="polite">{state.message}</p>}
  </div>;
}

/* Same-tab head viewer: existing direct children retain their own DOM owners. */
.head-comparison-module-page > .head-linked-viewer-tools {
  display: flex;
  flex: none;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 12px;
  min-width: 0;
  padding: 3px 16px;
  border-top: 1px solid #d5dfdc;
  background: #f8f7f2;
}
.head-linked-viewer-tools > button {
  min-height: 32px;
  flex: none;
  padding: 4px 9px;
  border: 1px solid #6f9990;
  border-radius: 6px;
  background: #fff;
  color: var(--green, #17483f);
  font: 600 13px/1.4 system-ui, sans-serif;
  cursor: pointer;
}
.head-linked-viewer-tools > button:disabled { cursor: wait; opacity: .7; }
.head-linked-viewer-tools > button:focus-visible { outline: 3px solid #16c6b2; outline-offset: 3px; }
.head-linked-viewer-tools > p { flex: 1 1 240px; margin: 0; font-size: 13px; overflow-wrap: anywhere; }
@media (min-width: 1200px) {
  .anatomy-site-frame .shoulder-module-page.atlas-3d-workspace-page.head-comparison-module-page:has(> .head-linked-viewer-tools) {
    grid-template-rows: auto auto auto minmax(0, 1fr) auto auto auto;
  }
  .anatomy-site-frame .head-comparison-module-page:has(> .head-linked-viewer-tools) > .atlas-body-learning-flow { grid-column: 1; grid-row: 5; }
  .anatomy-site-frame .head-comparison-module-page > .head-linked-viewer-tools { grid-column: 1; grid-row: 6; }
  .anatomy-site-frame .head-comparison-module-page:has(> .head-linked-viewer-tools) > .shoulder-module-notes { grid-column: 1; grid-row: 7; }
}
/* Fullscreen's top-layer host escapes the surrounding site navigation. Keep
   every action reachable in short/narrow viewports without overlaying the frame. */
.anatomy-site-frame .shoulder-module-page.head-comparison-module-page:fullscreen {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  width: 100dvw;
  height: 100dvh;
  min-width: 0;
  min-height: 0;
  max-height: none;
  overflow: auto;
  background: #f8f7f2;
}
.head-comparison-module-page:fullscreen > :not(.shoulder-module-frame) { flex-shrink: 0; }
.anatomy-site-frame .head-comparison-module-page:fullscreen > .shoulder-module-frame {
  flex: 1 0 280px;
  width: 100%;
  height: auto;
  min-height: 280px;
}
.head-comparison-module-page:fullscreen > .atlas-body-learning-flow { margin: 0; max-height: 35dvh; overflow: auto; }
